from django.db import migrations, models


def copy_sku_images_to_goods_image(apps, schema_editor):
    """把 SKU 的旧主图迁移到商品图片表，并标记为主图。"""
    GoodsSKU = apps.get_model("goods", "GoodsSKU")
    GoodsImage = apps.get_model("goods", "GoodsImage")

    for sku in GoodsSKU.objects.all().iterator():
        old_image = getattr(sku.image, "name", "") if sku.image else ""
        main_image = None

        if old_image:
            main_image = GoodsImage.objects.filter(
                sku_id=sku.pk,
                image=old_image,
            ).first()
            if main_image is None:
                main_image = GoodsImage.objects.create(
                    sku_id=sku.pk,
                    image=old_image,
                    is_main=True,
                )

        if main_image is None:
            main_image = GoodsImage.objects.filter(sku_id=sku.pk).order_by("pk").first()

        if main_image is not None:
            GoodsImage.objects.filter(sku_id=sku.pk).exclude(pk=main_image.pk).update(
                is_main=False
            )
            if not main_image.is_main:
                main_image.is_main = True
                main_image.save(update_fields=["is_main"])


